// IlmXL Social Studies content bank (Canada, Kindergarten to grade 12).
// Shape is defined in FORMAT.md. Helpers below build plain objects of that shape.
// Multiple-choice options are written with the right answer at the given index,
// then rotated by a fixed amount (from the question text) so the right answer
// is not always in the same place. The output is deterministic.

const L = (say, board) => ({ say, board });

function rot(q, n) {
  let h = 0;
  for (let i = 0; i < q.length; i++) h = (h * 31 + q.charCodeAt(i)) >>> 0;
  return h % n;
}

const mc = (q, choices, a, why) => {
  const n = choices.length;
  const k = rot(q, n);
  return { q, choices: choices.slice(k).concat(choices.slice(0, k)), a: (a - k + n) % n, why };
};

const ty = (q, answer, accept, why) => ({ q, answer, accept, why });

